1	package blueprint
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"os"
11		"path/filepath"
12		"strings"
13	)
14	
15	type CreateOptions struct {
16		Blueprint  string // required; subdirectory in the blueprints repo holding template.yaml + skeleton/
17		OutputDir  string
18		Version    string
19		SetValues  map[string]any
20		Files      []string
21		Force      bool
22		NoInput    bool
23		OutputJSON string // path to write CreateResult JSON; "-" means stdout
24		Stdin      io.Reader
25		Stdout     io.Writer
26		Stderr     io.Writer
27		HTTP       *http.Client
28		UserAgent  string
29	
30		// Test overrides. Production callers leave these zero-valued; the CLI
31		// always targets the official blueprint library at integrio-intropy/intropy-blueprints.
32		Owner         string
33		Repo          string
34		GitHubBaseURL string
35	}
36	
37	// CreateResult is the machine-readable summary written when --output-json is
38	// set. It is the contract chained scaffolder steps consume; field names are
39	// stable and additive-only.
40	type CreateResult struct {
41		Blueprint string         `json:"blueprint"`
42		Owner     string         `json:"owner"`
43		Repo      string         `json:"repo"`
44		Version   string         `json:"version"`
45		OutputDir string         `json:"outputDir"`
46		Values    map[string]any `json:"values"`
47	}
48	
49	func (o *CreateOptions) applyDefaults() {
50		if o.Owner == "" {
51			o.Owner = defaultBlueprintOwner
52		}
53		if o.Repo == "" {
54			o.Repo = defaultBlueprintRepo
55		}
56		if o.Stdin == nil {
57			o.Stdin = os.Stdin
58		}
59		if o.UserAgent == "" {
60			o.UserAgent = "intropy-cli"
61		}
62	}
63	
64	// Create runs the full scaffold: resolve release, download tarball, extract,
65	// load manifest, resolve values (with optional interactive prompting), render.
66	func Create(ctx context.Context, opts CreateOptions) error {
67		opts.applyDefaults()
68		if err := validateCreateOptions(opts); err != nil {
69			return err
70		}
71	
72		gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
73		tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
74		if err != nil {
75			return err
76		}
77		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)
78	
79		blueprintRoot, cleanup, err := downloadBlueprint(ctx, gh, opts.Owner, opts.Repo, tag, opts.Blueprint, "intropy-blueprint-*")
80		if err != nil {
81			return err
82		}
83		defer cleanup()
84	
85		tmpl, values, err := prepareCreateTemplate(blueprintRoot, opts)
86		if err != nil {
87			return err
88		}
89	
90		if err := renderCreateOutput(blueprintRoot, opts.Blueprint, opts.OutputDir, opts.Force, values); err != nil {
91			return err
92		}
93		fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (blueprint %s)\n", opts.OutputDir, opts.Owner, opts.Repo, tag, opts.Blueprint)
94	
95		return maybeWriteCreateResult(opts, tmpl, values, tag)
96	}
97	
98	func validateCreateOptions(opts CreateOptions) error {
99		if err := validateBlueprintName(opts.Blueprint); err != nil {
100			return err
101		}
102		if opts.OutputDir == "" {
103			return errors.New("--output is required")
104		}
105		return nil
106	}
107	
108	func prepareCreateTemplate(blueprintRoot string, opts CreateOptions) (*Template, map[string]any, error) {
109		tmpl, err := LoadTemplate(filepath.Join(blueprintRoot, templateManifestName))
110		if err != nil {
111			return nil, nil, err
112		}
113	
114		prompter := selectPrompter(&opts)
115		values, err := Resolve(tmpl, opts.Files, opts.Stdin, opts.SetValues, prompter)
116		if err != nil {
117			return nil, nil, err
118		}
119		return tmpl, values, nil
120	}
121	
122	func renderCreateOutput(blueprintRoot, blueprintName, outputDir string, force bool, values map[string]any) error {
123		skelRoot := filepath.Join(blueprintRoot, blueprintSkeletonDir)
124		if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
125			return fmt.Errorf("blueprint %q is missing %s/ directory", blueprintName, blueprintSkeletonDir)
126		}
127		if err := ensureOutputDir(outputDir, force); err != nil {
128			return err
129		}
130		return Render(skelRoot, outputDir, values)
131	}
132	
133	func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string) error {
134		if opts.OutputJSON == "" {
135			return nil
136		}
137	
138		absOut, err := filepath.Abs(opts.OutputDir)
139		if err != nil {
140			absOut = opts.OutputDir
141		}
142		result := CreateResult{
143			Blueprint: tmpl.Metadata.Name,
144			Owner:     opts.Owner,
145			Repo:      opts.Repo,
146			Version:   tag,
147			OutputDir: absOut,
148			Values:    values,
149		}
150		if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
151			return fmt.Errorf("write --output-json: %w", err)
152		}
153		return nil
154	}
155	
156	func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
157		data, err := json.MarshalIndent(r, "", "  ")
158		if err != nil {
159			return err
160		}
161		data = append(data, '\n')
162		if path == "-" {
163			_, err := stdout.Write(data)
164			return err
165		}
166		return os.WriteFile(path, data, 0o644)
167	}
168	
169	func ensureOutputDir(dir string, force bool) error {
170		info, err := os.Stat(dir)
171		switch {
172		case errors.Is(err, os.ErrNotExist):
173			return os.MkdirAll(dir, 0o755)
174		case err != nil:
175			return err
176		case !info.IsDir():
177			return fmt.Errorf("--output %s exists and is not a directory", dir)
178		}
179		entries, err := os.ReadDir(dir)
180		if err != nil {
181			return err
182		}
183		if len(entries) > 0 && !force {
184			return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
185		}
186		return nil
187	}
188	
189	// validateBlueprintName rejects empty names and anything that could escape the
190	// extracted tarball root via filepath.Join (separators, parent refs, hidden
191	// directories). The blueprint argument is user input that we turn directly into
192	// a path segment, so it has to be sanitized.
193	func validateBlueprintName(name string) error {
194		if name == "" {
195			return errors.New("blueprint name is required")
196		}
197		if name == "." || name == ".." || strings.HasPrefix(name, ".") {
198			return fmt.Errorf("invalid blueprint name %q", name)
199		}
200		if strings.ContainsAny(name, `/\`) {
201			return fmt.Errorf("invalid blueprint name %q (must be a single path segment)", name)
202		}
203		return nil
204	}
205	
206	func selectPrompter(opts *CreateOptions) Prompter {
207		if opts.NoInput {
208			return nil
209		}
210		// Only prompt when stdin is a real terminal. In CI / piped contexts the
211		// caller must supply values via --set or --values; otherwise Resolve
212		// returns a clean "missing required parameter(s)" error.
213		stdin, ok := opts.Stdin.(*os.File)
214		if !ok || !isTerminal(stdin.Fd()) {
215			return nil
216		}
217		return NewStdinPrompter(opts.Stdin, opts.Stderr)
218	}
