1	package skill
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path"
8		"path/filepath"
9	)
10	
11	type Project struct {
12		Root string
13	}
14	
15	var ErrProjectNotFound = errors.New("no skills.json found in current directory or any parent")
16	
17	// FindProject walks up from startDir looking for skills.json.
18	// Returns ErrProjectNotFound if no manifest is found before reaching the
19	// filesystem root.
20	func FindProject(startDir string) (*Project, error) {
21		abs, err := filepath.Abs(startDir)
22		if err != nil {
23			return nil, fmt.Errorf("absolute path: %w", err)
24		}
25	
26		for {
27			candidate := filepath.Join(abs, "skills.json")
28			if _, err := os.Stat(candidate); err == nil {
29				return &Project{Root: abs}, nil
30			} else if !os.IsNotExist(err) {
31				return nil, fmt.Errorf("stat %s: %w", candidate, err)
32			}
33	
34			parent := filepath.Dir(abs)
35			if parent == abs {
36				//Reached file system root.
37				return nil, ErrProjectNotFound
38			}
39			abs = parent
40		}
41	}
42	
43	// ManifestPath returns the absolute path to skills.json.
44	func (p *Project) ManifestPath() string {
45		return filepath.Join(p.Root, "skills.json")
46	}
47	
48	// LockfilePath returns the absolute path to skills.lock.json.
49	func (p *Project) LockfilePath() string {
50		return filepath.Join(p.Root, "skills.lock.json")
51	}
52	
53	// SkillsDir returns the canonical install directory: <root>/.agents/skills.
54	// Per §9 of the spec.
55	func (p *Project) SkillsDir() string {
56		return filepath.Join(p.Root, ".agents", "skills")
57	}
58	
59	// SkillDir returns the canonical install directory for a named skill:
60	// <root>/.agents/skills/<name>.
61	func (p *Project) SkillDir(name string) string {
62		return filepath.Join(p.SkillsDir(), name)
63	}
64	
65	// SkillRelPath returns the install directory relative to the project root,
66	// in forward-slash form. This is the value to write to the lockfile.
67	func (p *Project) SkillRelPath(name string) string {
68		return path.Join(".agents", "skills", name)
69	}
70	
71	// AdditionalDirs returns the absolute paths from a manifest entry's
72	// additionalBasePaths, with skill name appended to each. Returns an empty
73	// slice if the entry has no additionalBasePaths.
74	func (p *Project) AdditionalDirs(entry ManifestEntry) []string {
75		out := make([]string, 0, len(entry.AdditionalBasePaths))
76		for _, base := range entry.AdditionalBasePaths {
77			out = append(out, filepath.Join(p.Root, base, entry.Name))
78		}
79	
80		return out
81	}
82	
83	func (p *Project) AdditionalRelPaths(entry ManifestEntry) []string {
84		out := make([]string, 0, len(entry.AdditionalBasePaths))
85		for _, base := range entry.AdditionalBasePaths {
86			out = append(out, path.Join(filepath.ToSlash(base), entry.Name))
87		}
88		return out
89	}
90	
91	// LoadManifest reads and parses skills.json from the project root.
92	func (p *Project) LoadManifest() (*Manifest, error) {
93		return LoadManifest(p.ManifestPath())
94	}
95	
96	// SaveManifest writes the manifest to skills.json at the project root.
97	func (p *Project) SaveManifest(m *Manifest) error {
98		return SaveManifest(p.ManifestPath(), m)
99	}
100	
101	// LoadLockfile reads and parses skills.lock.json from the project root.
102	// Returns an empty lockfile (not an error) if the file doesn't exist yet.
103	func (p *Project) LoadLockfile() (*Lockfile, error) {
104		return LoadLockfile(p.LockfilePath())
105	}
106	
107	// SaveLockfile writes the lockfile to skills.lock.json at the project root.
108	func (p *Project) SaveLockfile(l *Lockfile) error {
109		return SaveLockfile(p.LockfilePath(), l)
110	}
