1	package blueprint
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"net/http"
9		"os"
10		"path/filepath"
11	)
12	
13	const (
14		defaultBlueprintOwner = "integrio-intropy"
15		defaultBlueprintRepo  = "intropy-blueprints"
16		templateManifestName  = "template.yaml"
17		blueprintSkeletonDir  = "skeleton"
18		githubAPIBaseURL      = "https://api.github.com"
19	)
20	
21	// GitHub talks to a GitHub-compatible API. BaseURL is overridable for tests.
22	type GitHub struct {
23		BaseURL   string
24		HTTP      *http.Client
25		Token     string
26		UserAgent string
27	}
28	
29	func newGitHub(client *http.Client, userAgent string) *GitHub {
30		if client == nil {
31			client = http.DefaultClient
32		}
33		return &GitHub{
34			BaseURL:   githubAPIBaseURL,
35			HTTP:      client,
36			Token:     os.Getenv("GITHUB_TOKEN"),
37			UserAgent: userAgent,
38		}
39	}
40	
41	// NewGitHubClient creates a configured GitHub client for external callers.
42	func NewGitHubClient(client *http.Client, userAgent, baseURL string) *GitHub {
43		gh := newGitHub(client, userAgent)
44		if baseURL != "" {
45			gh.BaseURL = baseURL
46		}
47		return gh
48	}
49	
50	func newConfiguredGitHub(client *http.Client, userAgent, baseURL string) *GitHub {
51		return NewGitHubClient(client, userAgent, baseURL)
52	}
53	
54	func resolveReleaseTag(ctx context.Context, gh *GitHub, owner, repo, requestedTag string) (string, error) {
55		if requestedTag != "" {
56			return requestedTag, nil
57		}
58		return gh.LatestTag(ctx, owner, repo)
59	}
60	
61	func downloadBlueprint(ctx context.Context, gh *GitHub, owner, repo, tag, blueprint, tempPattern string) (string, func(), error) {
62		rc, err := gh.Tarball(ctx, owner, repo, tag)
63		if err != nil {
64			return "", nil, err
65		}
66		defer rc.Close()
67	
68		tmpDir, err := os.MkdirTemp("", tempPattern)
69		if err != nil {
70			return "", nil, err
71		}
72		cleanup := func() { _ = os.RemoveAll(tmpDir) }
73	
74		if err := ExtractTarGz(rc, tmpDir); err != nil {
75			cleanup()
76			return "", nil, err
77		}
78	
79		blueprintRoot := filepath.Join(tmpDir, blueprint)
80		if info, err := os.Stat(blueprintRoot); err != nil || !info.IsDir() {
81			cleanup()
82			return "", nil, fmt.Errorf("blueprint %q not found in %s/%s@%s", blueprint, owner, repo, tag)
83		}
84		return blueprintRoot, cleanup, nil
85	}
86	
87	// LatestTag returns the tag_name of the most recent release for owner/repo.
88	func (g *GitHub) LatestTag(ctx context.Context, owner, repo string) (string, error) {
89		u := fmt.Sprintf("%s/repos/%s/%s/releases/latest", g.BaseURL, owner, repo)
90		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
91		if err != nil {
92			return "", err
93		}
94		req.Header.Set("Accept", "application/vnd.github+json")
95		g.addCommonHeaders(req)
96	
97		resp, err := g.HTTP.Do(req)
98		if err != nil {
99			return "", fmt.Errorf("github releases: %w", err)
100		}
101		defer resp.Body.Close()
102		if resp.StatusCode != http.StatusOK {
103			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
104			return "", fmt.Errorf("github releases: %s: %s", resp.Status, string(body))
105		}
106		var rel struct {
107			TagName string `json:"tag_name"`
108		}
109		if err := json.NewDecoder(resp.Body).Decode(&rel); err != nil {
110			return "", fmt.Errorf("decode release: %w", err)
111		}
112		if rel.TagName == "" {
113			return "", fmt.Errorf("github releases: empty tag_name")
114		}
