13	
14	type Prompter interface {
15		Prompt(field FieldSpec) (any, error)
16	}
17	
18	// StdinPrompter is a line-based prompter. Enums render as a numbered list;
19	// every other type flows through one read-coerce-validate-retry loop.
20	// Invalid input re-prompts; EOF aborts.
21	type StdinPrompter struct {
22		in      io.Reader
23		out     io.Writer
24		scanner *bufio.Scanner
25	}
26	
27	func NewStdinPrompter(in io.Reader, out io.Writer) *StdinPrompter {
28		return &StdinPrompter{in: in, out: out, scanner: bufio.NewScanner(in)}
29	}
30	
31	func (p *StdinPrompter) Prompt(f FieldSpec) (any, error) {
32		if len(f.Enum) > 0 {
33			return p.promptEnum(f)
34		}
35		return p.promptScalar(f)
36	}
37	
38	func (p *StdinPrompter) promptScalar(f FieldSpec) (any, error) {
39		var re *regexp.Regexp
40		if f.Pattern != "" {
41			var err error
42			re, err = regexp.Compile(f.Pattern)
43			if err != nil {
44				return nil, fmt.Errorf("invalid pattern for %q: %w", f.Name, err)
45			}
46		}
47		for {
48			p.writeLabel(f)
49			raw, ok, err := p.readLine()
50			if err != nil {
51				return nil, err
52			}
53			if !ok {
54				return nil, io.EOF
55			}
56			if raw == "" {
57				return f.Default, nil
58			}
59			v := coerce(raw, f.Type)
60			if isTypedField(f.Type) {
61				if _, stillStr := v.(string); stillStr {
62					fmt.Fprintf(p.out, "  ! %q is not a valid %s\n", raw, f.Type)
63					continue
64				}
65			}
66			if re != nil {
67				s, ok := v.(string)
68				if !ok || !re.MatchString(s) {
69					fmt.Fprintf(p.out, "  ! value must match %s\n", f.Pattern)
70					continue
71				}
72			}
73			return v, nil
74		}
75	}
76	
77	func (p *StdinPrompter) promptEnum(f FieldSpec) (any, error) {
78		p.writeHeading(f)
79		options := make([]string, 0, len(f.Enum))
80		for i, e := range f.Enum {
81			s := fmt.Sprint(e)
82			options = append(options, s)
83			fmt.Fprintf(p.out, "  %d) %s\n", i+1, s)
84		}
85		defStr, hasDef := f.Default.(string)
86		for {
87			if hasDef {
88				fmt.Fprintf(p.out, "[%s]: ", defStr)
89			} else {
90				fmt.Fprint(p.out, ": ")
91			}
92			raw, ok, err := p.readLine()
93			if err != nil {
94				return nil, err
95			}
96			if !ok {
97				return nil, io.EOF
98			}
99			if raw == "" {
100				if hasDef {
101					return coerce(defStr, f.Type), nil
102				}
103				fmt.Fprintln(p.out, "  ! please choose one")
104				continue
105			}
106			if n, err := strconv.Atoi(raw); err == nil && n >= 1 && n <= len(options) {
107				return coerce(options[n-1], f.Type), nil
108			}
109			for _, o := range options {
110				if o == raw {
111					return coerce(o, f.Type), nil
112				}
113			}
114			fmt.Fprintf(p.out, "  ! %q is not one of the options\n", raw)
115		}
116	}
117	
118	func (p *StdinPrompter) writeLabel(f FieldSpec) {
119		label := f.Name
120		if f.Title != "" {
121			label = f.Title
122		}
123		if f.Description != "" {
124			label = fmt.Sprintf("%s (%s)", label, f.Description)
125		}
126		switch d := f.Default.(type) {
127		case bool:
128			if d {
129				label += " [Y/n]"
130			} else {
131				label += " [y/N]"
132			}
133		case nil:
134			if f.Type == "boolean" {
135				label += " [y/n]"
136			}
137		default:
138			label = fmt.Sprintf("%s [%v]", label, d)
139		}
140		fmt.Fprintf(p.out, "%s: ", label)
141	}
142	
143	func (p *StdinPrompter) writeHeading(f FieldSpec) {
144		title := f.Name
145		if f.Title != "" {
146			title = f.Title
147		}
148		if f.Description != "" {
149			fmt.Fprintf(p.out, "%s (%s)\n", title, f.Description)
150		} else {
151			fmt.Fprintln(p.out, title)
152		}
153	}
154	
155	func (p *StdinPrompter) readLine() (string, bool, error) {
156		if !p.scanner.Scan() {
157			if err := p.scanner.Err(); err != nil {
158				return "", false, err
159			}
160			return "", false, nil
161		}
162		return strings.TrimSpace(p.scanner.Text()), true, nil
163	}
164	
165	func isTypedField(typ string) bool {
166		return typ == "boolean" || typ == "integer" || typ == "number"
167	}
168	
169	// coerce parses a string into the type declared by a JSON Schema property.
170	// Returns the original string if parsing fails — JSON Schema validation
171	// downstream produces a clean type error in that case.
172	func coerce(s, typ string) any {
173		switch typ {
174		case "boolean":
175			switch strings.ToLower(s) {
176			case "y", "yes", "true", "1":
177				return true
178			case "n", "no", "false", "0":
179				return false
180			}
181		case "integer":
182			if i, err := strconv.ParseInt(s, 10, 64); err == nil {
183				return i
184			}
185		case "number":
186			if v, err := strconv.ParseFloat(s, 64); err == nil {
187				return v
188			}
189		}
190		return s
191	}
192	
193	func isTerminal(fd uintptr) bool {
194		return term.IsTerminal(int(fd))
195	}
